    'https://api.open-meteo.com/v1/forecast?latitude=-23.55&longitude=-46.63&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=America%2FSao_Paulo&forecast_days=1'
  );

  const important = [];
  for (const e of emails) {
    const j = await judge.important(e);
    if (j.p >= 0.5) important.push(e);
  }

  const sortedEvents = [...events].sort((a, b) => new Date(a.start) - new Date(b.start));

  const weekday = new Intl.DateTimeFormat('pt-BR', { timeZone: tz, weekday: 'long' }).format(nowDate);
  const dateLabel = `${weekday}, ${d}/${mo}`;

  const timeFmt = new Intl.DateTimeFormat('pt-BR', { timeZone: tz, hour: '2-digit', minute: '2-digit', hour12: false });

  const agendaLines = sortedEvents.length === 0
    ? 'Nenhum evento hoje.'
    : sortedEvents.map(ev => `• ${timeFmt.format(new Date(ev.start))} ${ev.title}`).join('\n');

  const emailLines = important.length === 0
    ? 'Nenhum email importante.'
    : important.map(e => `• ${e.from_name}: ${e.subject}`).join('\n');

