    ? 'Previsão indisponível.'
    : `Tempo em SP: ${tmin}°C a ${tmax}°C${precip !== undefined ? `, ${precip}% de chance de chuva` : ''}.`;

  const text = `Bom dia! Resumo de ${dateLabel}\n\nAgenda:\n${agendaLines}\n\nEmails importantes:\n${emailLines}\n\n${weatherLine}`;

  log('Enviando resumo pelo Telegram...');
  await telegram.send({ text });
}

async function run() {
  const nowISO = now();
  const offsetMatch = nowISO.match(/(Z|[+-]\d{2}:\d{2})$/);
  const offset = offsetMatch ? offsetMatch[0] : '+00:00';
  const dateStr = nowISO.slice(0, 10);
  const from = dateStr + 'T00:00:00' + offset;
  const to = dateStr + 'T23:59:59' + offset;

  log('Buscando agenda de ' + dateStr);
  const events = await calendar.events({ from, to });
