    agendaText = 'Nenhum evento hoje';
  } else {
    agendaText = sortedEvents.map(function(e) {
      const time = e.start.slice(11, 16);
      return '• ' + time + ' ' + e.title;
    }).join('\n');
  }

  log('Buscando emails não lidos');
  const emails = await gmail.search({ query: 'in:inbox is:unread', days: 1, unread: true, max: 20 });

  const importantEmails = [];
  for (const email of (emails || [])) {
    const verdict = await judge.important(email);
    if (verdict && verdict.p >= 0.5) {
      importantEmails.push(email);
    }
  }

  let emailsText;
  if (importantEmails.length === 0) {
    emailsText = 'Nenhum email importante';
  } else {
    emailsText = importantEmails.map(function(e) {
      return '• ' + (e.from_name || e.from) + ': ' + e.subject;
    }).join('\n');
