  const tmin = weather && weather.daily && weather.daily.temperature_2m_min ? weather.daily.temperature_2m_min[0] : null;
  const precip = weather && weather.daily && weather.daily.precipitation_probability_max ? weather.daily.precipitation_probability_max[0] : null;

  const parts = dateStr.split('-');
