async function run() {
  const nowIso = now();
  const nowDate = new Date(nowIso);
  const todayMid = new Date(nowDate.getFullYear(), nowDate.getMonth(), nowDate.getDate());
  const limit = new Date(todayMid.getTime() + 7 * 24 * 60 * 60 * 1000);

  const emails = await gmail.search({ query: "boleto OR fatura OR invoice OR vencimento", days: 30, max: 30 });
  log("emails encontrados: " + emails.length);

  function parseBRDate(s) {
    const parts = s.split("/");
    const d = parseInt(parts[0], 10);
    const m = parseInt(parts[1], 10);
    const y = parseInt(parts[2], 10);
    return new Date(y, m - 1, d);
  }

  function parseAmount(s) {
    return parseFloat(s.replace(/\./g, "").replace(",", "."));
  }

  function formatBRL(n) {
    const fixed = n.toFixed(2);
    const dot = fixed.indexOf(".");
    const intPart = fixed.slice(0, dot);
    const decPart = fixed.slice(dot + 1);
    let withDots = "";
    let count = 0;
    for (let i = intPart.length - 1; i >= 0; i--) {
      withDots = intPart[i] + withDots;
      count++;
      if (count % 3 === 0 && i !== 0) withDots = "." + withDots;
    }
    return withDots + "," + decPart;
  }

  const dateRe = /venc\w*[^\d]{0,20}(\d{2}\/\d{2}\/\d{4})/i;
  const amountRe = /R\$\s*([\d.,]+)/;

  const items = [];
  for (const e of emails) {
    const text = (e.subject || "") + " " + (e.snippet || "");
    const dm = text.match(dateRe);
    const am = text.match(amountRe);
    if (!dm || !am) continue;
    const dueStr = dm[1].slice(0, 5);
    const dueDate = parseBRDate(dm[1]);
    const amountNum = parseAmount(am[1]);
    if (isNaN(amountNum) || isNaN(dueDate.getTime())) continue;
    if (dueDate >= todayMid && dueDate <= limit) {
      items.push({ dueDate, dueStr, amountNum, amountRaw: am[1], subject: e.subject });
    }
  }

  if (items.length === 0) {
    log("nenhuma conta vencendo nos proximos 7 dias");
    return;
  }

  items.sort((a, b) => a.dueDate - b.dueDate);

  let total = 0;
  const lines = items.map((it) => {
    total += it.amountNum;
    return "• " + it.dueStr + " — " + it.subject + ": R$ " + it.amountRaw;
  });

  const text = "Contas vencendo nos próximos 7 dias:\n\n" + lines.join("\n") + "\n\nTotal: R$ " + formatBRL(total);
  await telegram.send({ text });
}

