async function run() {
  const nowIso = now();
  const nowDate = new Date(nowIso);

  // Window: tomorrow 00:00 through 6 days later 23:59:59 (7 days total)
  const start = new Date(nowDate);
  start.setDate(start.getDate() + 1);
  start.setHours(0, 0, 0, 0);
  const end = new Date(start);
  end.setDate(end.getDate() + 6);
  end.setHours(23, 59, 59, 999);

  log(`Fetching events from ${start.toISOString()} to ${end.toISOString()}`);
  const events = await calendar.events({ from: start.toISOString(), to: end.toISOString() });

  const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const pad = (n) => String(n).padStart(2, '0');

  const buckets = [];
  for (let i = 0; i < 7; i++) {
    const d = new Date(start);
    d.setDate(d.getDate() + i);
    buckets.push({ date: d, events: [] });
  }

  for (const ev of events) {
    const evStart = new Date(ev.start);
    for (const b of buckets) {
      if (
        evStart.getFullYear() === b.date.getFullYear() &&
        evStart.getMonth() === b.date.getMonth() &&
        evStart.getDate() === b.date.getDate()
      ) {
        b.events.push(ev);
        break;
      }
    }
  }

  const lines = ['Your week ahead:'];
  for (const b of buckets) {
    lines.push('');
    lines.push(`${dayNames[b.date.getDay()]} ${pad(b.date.getDate())}/${pad(b.date.getMonth() + 1)}`);
    if (b.events.length === 0) {
      lines.push('• nothing scheduled');
    } else {
      b.events.sort((a, c) => new Date(a.start) - new Date(c.start));
      for (const ev of b.events) {
        const t = new Date(ev.start);
        lines.push(`• ${pad(t.getHours())}:${pad(t.getMinutes())} ${ev.title}`);
      }
    }
  }

  const text = lines.join('\n');
  log(text);
  await telegram.send({ text });
}

async function run() {
  const nowIso = now();
  const current = new Date(nowIso);

  // Window: tomorrow 00:00 through 6 days later 23:59:59 (next 7 days)
  const start = new Date(current.getFullYear(), current.getMonth(), current.getDate() + 1, 0, 0, 0);
  const end = new Date(current.getFullYear(), current.getMonth(), current.getDate() + 7, 23, 59, 59);

  log('Fetching events from ' + start.toISOString() + ' to ' + end.toISOString());
  const events = await calendar.events({ from: start.toISOString(), to: end.toISOString() });

  const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  function pad(n) { return n < 10 ? '0' + n : '' + n; }

  // Build 7 day buckets in order, keyed by local YYYY-MM-DD
  const days = [];
  for (let i = 0; i < 7; i++) {
    const d = new Date(start.getFullYear(), start.getMonth(), start.getDate() + i);
    const key = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
    days.push({ date: d, key: key, label: WEEKDAYS[d.getDay()] + ' ' + pad(d.getDate()) + '/' + pad(d.getMonth() + 1), events: [] });
  }

  for (const ev of (events || [])) {
    if (!ev || !ev.start) continue;
    const evDate = new Date(ev.start);
    const key = evDate.getFullYear() + '-' + pad(evDate.getMonth() + 1) + '-' + pad(evDate.getDate());
    const bucket = days.find(d => d.key === key);
    if (bucket) bucket.events.push(ev);
  }

  for (const day of days) {
    day.events.sort((a, b) => new Date(a.start) - new Date(b.start));
  }

  const lines = ['Your week ahead:', ''];
  for (const day of days) {
    lines.push(day.label);
    if (day.events.length === 0) {
      lines.push('• nothing scheduled');
    } else {
      for (const ev of day.events) {
        const t = new Date(ev.start);
        const hh = pad(t.getHours());
        const mm = pad(t.getMinutes());
        lines.push('• ' + hh + ':' + mm + ' ' + ev.title);
      }
    }
    lines.push('');
  }
  while (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();

  const text = lines.join('\n');
  log('Sending weekly agenda:\n' + text);
  await telegram.send({ text: text });
}

async function run() {
  const emails = await gmail.search({
    query: 'tracking OR rastreio OR "código de rastreamento" OR shipped OR enviado',
    days: 14,
    max: 20
  });

  const codeRegex = /(?:tracking(?:\s*number)?|c[oó]digo de rastreio|c[oó]digo de rastreamento)[:\s]+([A-Za-z0-9]{8,20})/i;

  const seenCodes = new Set();
  const packages = [];

  for (const email of emails) {
    const text = `${email.subject || ''} ${email.snippet || ''}`;
    const match = text.match(codeRegex);
    if (match && match[1]) {
      const code = match[1].toUpperCase();
      if (!seenCodes.has(code)) {
        seenCodes.add(code);
        packages.push({ code, email });
      }
    }
  }

  if (packages.length === 0) {
    log('No shipping notifications with tracking codes found.');
    return;
  }

  const lines = [];
  for (const pkg of packages) {
    let track;
    try {
      track = await http.getJSON(`https://api.trackingmore.example/v1/track?code=${pkg.code}`);
    } catch (e) {
      log(`Failed to look up ${pkg.code}: ${e}`);
      continue;
    }
    const statusText = (track && track.status ? String(track.status) : 'unknown').replace(/_/g, ' ');
    const lastEvent = track && track.last_event ? track.last_event : 'no update available';
    const etaPart = track && track.eta ? `, ETA ${track.eta}` : '';
    const who = pkg.email.from_name || pkg.email.from || 'Unknown sender';
    lines.push(`• ${pkg.code} (${who}): ${statusText} — ${lastEvent}${etaPart}`);
  }

  if (lines.length === 0) {
    log('No package statuses could be retrieved.');
    return;
  }

  const text = `📦 Package status\n\n${lines.join('\n')}`;
  await telegram.send({ text });
}

async function run() {
  const nowIso = now();
  const offsetMatch = nowIso.match(/(Z|[+-]\d{2}:\d{2})$/);
  const offset = offsetMatch ? offsetMatch[0] : 'Z';
  const datePart = nowIso.slice(0, 10);
  const d = new Date(datePart + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + 1);
  const tomorrow = d.toISOString().slice(0, 10);
  const from = tomorrow + 'T00:00:00' + offset;
  const to = tomorrow + 'T23:59:59' + offset;

  const events = await calendar.events({ from, to });
  const withAttendees = (events || [])
    .filter(e => Array.isArray(e.attendees) && e.attendees.length > 0)
    .sort((a, b) => new Date(a.start) - new Date(b.start));

  if (withAttendees.length === 0) {
    log('Nenhuma reunião de amanhã com convidados. Nada a enviar.');
    return;
  }

  const blocks = [];
  for (const ev of withAttendees) {
    const timeMatch = ev.start.match(/T(\d{2}):(\d{2})/);
    const timeLabel = timeMatch ? `${timeMatch[1]}:${timeMatch[2]}` : '';

    const lines = [`${timeLabel} ${ev.title}`];

    const seen = new Set();
    for (const email of ev.attendees) {
      if (seen.has(email)) continue;
      seen.add(email);
      const results = await gmail.search({ query: `from:${email}`, days: 14, max: 5 });
      for (const msg of (results || [])) {
        const note = msg.replied === false ? ' (sem resposta)' : '';
        const who = msg.from_name || msg.from;
        lines.push(`• ${who} — "${msg.subject}": ${msg.snippet}${note}`);
      }
    }

    blocks.push(lines.join('\n'));
  }

  const dayLabel = tomorrow.split('-').reverse().slice(0, 2).join('/');
  const text = `Preparação para amanhã (${dayLabel})\n\n` + blocks.join('\n\n');

  await telegram.send({ text });
  log('Resumo de preparação enviado.');
}

async function run() {
  const THRESHOLD = 5.40;
  const url = "https://api.exchangerate.example/v1/latest?base=USD&symbols=BRL";
  const data = await http.getJSON(url);

  const rate = data && data.rates && data.rates.BRL;
  if (typeof rate !== "number") {
    log("No valid BRL rate found in response, skipping.");
    return;
  }

  log(`USD→BRL rate: ${rate}`);

  if (rate > THRESHOLD) {
    const formatted = rate.toFixed(2);
    await telegram.send({ text: `💵 USD→BRL is at ${formatted}, above your ${THRESHOLD.toFixed(2)} threshold.` });
  } else {
    log(`Rate ${rate} is at or below threshold ${THRESHOLD}, no alert sent.`);
  }
}

async function run() {
  const nowIso = now();
  const nowDate = new Date(nowIso);
  const THRESHOLD_DAYS = 3;

  const emails = await gmail.search({
    query: "in:inbox -from:me",
    days: 30,
    max: 50
  });

  const fmt = new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric' });

  const candidates = [];
  for (const email of emails) {
    if (email.replied) continue;
    const sentDate = new Date(email.date);
    const ageDays = (nowDate - sentDate) / (1000 * 60 * 60 * 24);
    if (ageDays <= THRESHOLD_DAYS) continue;
    candidates.push(email);
  }

  const waiting = [];
  for (const email of candidates) {
    const { p } = await judge.needs_reply(email);
    if (p >= 0.5) {
      waiting.push(email);
    }
  }

  if (waiting.length === 0) {
    log("No overdue emails from real people needing a reply.");
    return;
  }

  waiting.sort((a, b) => new Date(a.date) - new Date(b.date));

  const lines = waiting.map(e => {
    const label = e.from_name || e.from;
    const since = fmt.format(new Date(e.date));
    return `• ${label} — "${e.subject}" (since ${since})`;
  });

  const text = `Waiting on your reply (3+ days):\n\n${lines.join('\n')}`;
  await telegram.send({ text });
  log(`Sent list of ${waiting.length} overdue email(s).`);
}

async function run() {
  const MONTHS = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];

  function dateLabel(iso) {
    // avoid Intl entirely; parse the date part straight out of the ISO string
    const datePart = iso.split("T")[0];
    const parts = datePart.split("-").map(Number);
    const y = parts[0], m = parts[1], d = parts[2];
    return MONTHS[m - 1] + " " + d;
  }

  const nowIso = now();
  const nowMs = new Date(nowIso).getTime();
  const THREE_DAYS_MS = 3 * 24 * 60 * 60 * 1000;

  const emails = await gmail.search({ query: "in:inbox -from:me", days: 30, max: 50 });

  const candidates = (emails || []).filter((e) => {
    if (e.replied) return false;
    const ageMs = nowMs - new Date(e.date).getTime();
    return ageMs > THREE_DAYS_MS;
  });

  const overdue = [];
  for (const e of candidates) {
    const verdict = await judge.needs_reply(e);
    if (verdict.p >= 0.5) {
      overdue.push(e);
    }
  }

  if (overdue.length === 0) {
    log("No overdue emails from real people needing a reply.");
    return;
  }

  overdue.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  const lines = overdue.map((e) => {
    const name = e.from_name || e.from;
    return "• " + name + " — \"" + e.subject + "\" (since " + dateLabel(e.date) + ")";
  });

  const text = "Waiting on your reply (3+ days):\n\n" + lines.join("\n");
  await telegram.send({ text });
}

async function run() {
  const pad2 = (n) => String(n).padStart(2, "0");

  const nowIso = now();
  const nowDate = new Date(nowIso);
  const OFFSET_HOURS = -3; // user is in Brazil (-03:00), matching the recorded routine

  // Compute "today" and "tomorrow" as wall-clock dates in -03:00
  const offsetDate = new Date(nowDate.getTime() + OFFSET_HOURS * 3600 * 1000);
  const todayDateObj = new Date(Date.UTC(
    offsetDate.getUTCFullYear(),
    offsetDate.getUTCMonth(),
    offsetDate.getUTCDate()
  ));
  const tomorrowDateObj = new Date(todayDateObj.getTime() + 24 * 3600 * 1000);

  const fmt = (d) => `${d.getUTCFullYear()}-${pad2(d.getUTCMonth() + 1)}-${pad2(d.getUTCDate())}`;
  const fmtDisplay = (d) => `${pad2(d.getUTCDate())}/${pad2(d.getUTCMonth() + 1)}`;

  const todayStr = fmt(todayDateObj);
  const tomorrowStr = fmt(tomorrowDateObj);

  const from = `${todayStr}T00:00:00-03:00`;
  const to = `${tomorrowStr}T23:59:59-03:00`;

  const events = await calendar.events({ from, to });

  const extractName = (title) => {
    const m = (title || "").match(/^Anivers[aá]rio de (.+)$/i);
    return m ? m[1].trim() : (title || "").trim();
  };

  const todayNames = [];
  const tomorrowNames = [];

  for (const ev of events) {
    if (ev.calendar !== "Birthdays") continue;
    const evDateStr = (ev.start || "").slice(0, 10);
    const name = extractName(ev.title);
    if (!name) continue;
    if (evDateStr === todayStr) {
      todayNames.push(name);
    } else if (evDateStr === tomorrowStr) {
      tomorrowNames.push(name);
    }
  }

  if (todayNames.length === 0 && tomorrowNames.length === 0) {
    log("Nenhum aniversário hoje ou amanhã no calendário Birthdays.");
    return;
  }

  const lines = [];
  if (todayNames.length > 0) {
    lines.push(`Hoje (${fmtDisplay(todayDateObj)}): ${todayNames.join(", ")}`);
  }
  if (tomorrowNames.length > 0) {
    lines.push(`Amanhã (${fmtDisplay(tomorrowDateObj)}): ${tomorrowNames.join(", ")}`);
  }

  const text = `🎂 Aniversários\n\n${lines.join("\n")}`;
  await telegram.send({ text });
}
